// Build ONE pending row from an untrusted payload.
//
// THE INJECTION THIS GUARDS. knowledge.pending.jsonl is newline-delimited: one row per line.
// A dictated note containing a newline — trivially produced by saying "new line", and produced
// by accident whenever a transcript breaks a sentence — would end the row early and let the
// remainder parse as a SECOND row, forging a fact nobody said. JSON.stringify escapes newlines
// to \n, so the row is built by stringifying an object and never by concatenating strings.
// This is the JSONL twin of the CR/LF header injection the contact workflow guards against.
//
// The note text is carried VERBATIM into the object. What was said is the fact; what it meant
// is a reading the review queue exists to gate.

const cfg = $('Config').first().json;
const body = $('Note received').first().json.body ?? {};

// ACCEPT WHAT ACTUALLY ARRIVES, from either caller.
//
// An iOS Shortcut POSTs {text}. The MCP tool posts {input}: n8n's MCP Server Trigger presents
// every attached tool to the client as a single freeform `input` field, regardless of the
// parameter schema configured on the tool node — verified against a live tools/list, where a
// tool declaring text+capturedAt still advertised only `input`. Reading body.text alone meant
// every note captured through MCP arrived empty and was dropped, while the client was told it
// succeeded. A model may also hand back the whole object as a JSON string, so try that too.
function noteText(b) {
  if (typeof b.text === 'string' && b.text.trim()) return b.text;
  const inp = b.input;
  if (typeof inp === 'string' && inp.trim()) {
    const s = inp.trim();
    if (s.startsWith('{')) {
      try {
        const parsed = JSON.parse(s);
        if (typeof parsed.text === 'string' && parsed.text.trim()) return parsed.text;
      } catch { /* not JSON — it is just the note, fall through */ }
    }
    return inp;
  }
  if (inp && typeof inp === 'object' && typeof inp.text === 'string') return inp.text;
  return '';
}

const raw = noteText(body);
const text = raw.trim();

if (!text) {
  return [{ json: { ok: false, reason: 'empty note — nothing was said', skip: true } }];
}

// A dictation is a sentence, not a document. Cap it so a malformed or hostile client cannot
// push an unbounded string into a file the app parses on every poll.
const MAX = 2000;
const clipped = text.length > MAX;
const value = clipped ? text.slice(0, MAX) : text;

const capturedAt = typeof body.capturedAt === 'string' && !Number.isNaN(Date.parse(body.capturedAt))
  ? new Date(body.capturedAt).toISOString()
  : new Date().toISOString();

// Subject is derived from the timestamp, not from the text: deriving it from a transcript
// would mint an entity out of a possibly-misheard proper noun before any human saw it.
const subject = `urn:kbase:concept/note-${capturedAt.replace(/[:.]/g, '-')}`;

const row = {
  subject,
  predicate: 'urn:kbase:predicate/captured-note',
  object: value,
  kb: cfg.TARGET_GRAPH,
  type: 'observation',
  agent: 'ios-shortcut',
  note: `Dictated ${capturedAt}${clipped ? ' (truncated at 2000 chars)' : ''}`,
  addedAt: capturedAt
};

// One line, newline-terminated. JSON.stringify guarantees no raw newline survives inside it.
const line = JSON.stringify(row) + '\n';
if (line.split('\n').length !== 2) {
  throw new Error('refusing to write a row containing a newline');
}

return [{ json: { ok: true, skip: false, line, subject, capturedAt, clipped } }];
